#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path
import datetime
import json

ROOT = Path.cwd()
while ROOT != ROOT.parent and not (ROOT / "package.json").exists():
    ROOT = ROOT.parent

brief = Path(__file__).with_name("017Q2_IMPLEMENTATION_BRIEF.md")
report = Path(__file__).with_name("017Q2_PRECHECK_REPORT.md")

targets = [
    "src/pdi/isometric/engine/IsometrieModuleV48d.tsx",
    "src/pdi/isometric/engine/pdiAlignParallel017Q.ts",
    "src/pdi/isometric/types/isoGraphTypes.ts",
    "src/pdi/model/pdiUniversalEntity.ts",
    "src/pdi/model/pdiUniversalAdapter.ts",
    "src/pdi/isometric/ui/PdiUniversalPropertyInspector.tsx",
]

rows = []
for rel in targets:
    p = ROOT / rel
    rows.append({
        "path": rel,
        "exists": p.exists(),
        "bytes": p.stat().st_size if p.exists() else None,
    })

brief.write_text('# PD&I PATCH 017Q2 — ALIGN / PARALLEL UNIVERSEL + PROPRIÉTÉS BIDIRECTIONNELLES\n\n## Objectif\n\nFaire évoluer PD&I vers ~85 % de maturité en consolidant deux axes :\n\n1. **ALIGN / PARALLELE** doivent fonctionner sur tout élément géométriquement compatible du dessin, et non uniquement sur les nœuds ou quelques tronçons.\n2. **PdiUniversalEntity / pdiUniversalAdapter / PdiUniversalPropertyInspector** doivent fonctionner réellement dans les deux sens : lecture ET écriture vers le modèle PD&I persistant.\n\nLe dépôt GitHub actuel est la réalité du code. Ne pas créer de deuxième moteur, deuxième renderer, deuxième store de sélection, deuxième historique ou deuxième base par type d\'objet.\n\n---\n\n## 0 — RÈGLE DE PATCH\n\nAvant toute modification :\n\n- auditer les fichiers réels ;\n- identifier les handlers et types réellement utilisés ;\n- faire une sauvegarde ;\n- vérifier les usages de `pdiAlignParallel017Q`, `commitGraph`, `pushHistory`, `undoGraph`, `redoGraph`, `PdiUniversalEntity`, `pdiUniversalAdapter` et `PdiUniversalPropertyInspector` ;\n- ne pas réécrire massivement `IsometrieModuleV48d.tsx` ;\n- ne pas supprimer une fonction existante sans preuve qu\'elle est remplacée ;\n- ne pas pousser vers GitHub automatiquement.\n\nAprès modification : build, tests, rapport PASS/PARTIAL/FAIL.\n\n---\n\n# 1 — ALIGN UNIVERSEL\n\n## But\n\nUne sélection doit pouvoir être alignée sur une référence choisie explicitement.\n\nWorkflow :\n\n**Sélection → référence → anchor → opération → preview → validation → commit → Undo**\n\nLes types supportés doivent être ceux que le modèle possède réellement, notamment :\n\n- `IsoNode`\n- `IsoSegment`\n- `IsoFitting`\n- équipement / vanne si représentés par `IsoNode`\n- supports\n- CAD2D\n- dimensions lorsqu\'elles possèdent une géométrie/association transformable.\n\nNe pas prétendre qu\'un type est transformable s\'il n\'a pas de géométrie persistante.\n\n## Anchors\n\nRéutiliser `extractEntityAnchors()` et les anchors existants :\n\n- node\n- endpoint_from\n- endpoint_to\n- midpoint\n- port\n- center\n- custom\n\nNe pas créer un deuxième système de points.\n\n## Transformation\n\nUn alignement doit modifier les coordonnées/rotations réelles du modèle.\n\nInterdit :\n\n- CSS transform ;\n- déplacement visuel seulement ;\n- deuxième renderer ;\n- deuxième modèle géométrique.\n\n### Node\n\nModifier `x/y/z`.\n\n### Segment\n\nUn segment est défini par ses nœuds.\n\nLorsqu\'un segment est aligné :\n\n- déterminer les extrémités réellement concernées ;\n- préserver la longueur lorsque le mode le demande ;\n- ne pas casser les connexions ;\n- ne pas déplacer un nœud partagé isolément si cela déforme involontairement d\'autres branches.\n\n### Fitting / vanne / équipement\n\nUtiliser les nodes, ports, orientation et rotation déjà présents.\n\n### Support\n\nRespecter sa relation géométrique existante avec la tuyauterie.\n\n### CAD2D\n\nModifier ses coordonnées réelles, pas uniquement le rendu SVG.\n\n### Dimension\n\nConserver ses anchors/relations si elle est liée à une géométrie.\n\n---\n\n# 2 — TOPOLOGIE ALIGN\n\nAvant validation :\n\n- détecter les nœuds partagés ;\n- calculer le degré de connexion ;\n- détecter les risques de déformation ;\n- conserver `pdiFindCoincidentNodes()`.\n\nSi un nœud possède plusieurs connexions, ne jamais déplacer silencieusement ce seul nœud si cela produit un réseau incohérent.\n\nSelon le cas :\n\n- déplacer le sous-graphe concerné ;\n- déplacer l\'ensemble de la sélection connectée ;\n- ou refuser avec un message explicite.\n\nAprès transformation :\n\n- connexions valides ;\n- ports valides ;\n- IDs inchangés ;\n- pas de collision interdite ;\n- longueurs cohérentes.\n\n---\n\n# 3 — PARALLELE UNIVERSEL\n\nWorkflow :\n\n**Sélection → référence → anchor/pivot → direction → preview → validation → Undo**\n\nSupporter au minimum :\n\n- tube + tube ;\n- plusieurs tubes ;\n- référence explicite ;\n- pivot `from` ;\n- pivot `to` ;\n- `midpoint` ;\n- direction ISO ;\n- direction 3D si déjà supportée.\n\nPour les éléments non linéaires, utiliser leur axe/direction réellement disponible. S\'il n\'existe pas de direction valide, refuser proprement au lieu de simuler.\n\nPréserver les longueurs et connexions lorsque possible.\n\nAucun élément non sélectionné ne doit bouger.\n\n---\n\n# 4 — PREVIEW\n\nLa preview ne doit pas modifier définitivement le modèle.\n\nPendant preview :\n\n- état temporaire ;\n- rendu temporaire ;\n- aucune persistance JSON ;\n- `Escape` annule.\n\nValidation :\n\n- une seule opération métier ;\n- `commitGraph()` ;\n- une seule entrée Undo.\n\n---\n\n# 5 — SÉLECTION UNIVERSELLE\n\nNe pas créer un nouveau store.\n\nLe moteur possède déjà plusieurs sélections :\n\n- `selectedNodeIds`\n- `selectedSegmentIds`\n- `selectedFittingIds`\n- `selectedCad2dIds`\n\nCréer seulement une abstraction légère au-dessus si nécessaire :\n\n```ts\n{\n  id: string;\n  kind: "node" | "segment" | "fitting" | "cad2d" | "support" | "dimension" | "equipment";\n}\n```\n\nCette abstraction sert à ALIGN/PARALLELE mais ne devient pas une deuxième source de vérité.\n\n---\n\n# 6 — PROPRIÉTÉS BIDIRECTIONNELLES\n\nObjectif :\n\n```text\nMODELE\n  ↕\nPdiUniversalEntity\n  ↕\nPdiUniversalPropertyInspector\n```\n\nPas seulement :\n\n```text\nMODELE → UniversalEntity → Inspector\n```\n\nLorsqu\'une propriété est modifiée :\n\n```text\nInspector\n→ UniversalEntity\n→ adapter inverse\n→ IsoNode / IsoSegment / IsoFitting / CAD2D / support\n→ commitGraph()\n→ renderer 2D\n→ viewer 3D\n→ JSON\n```\n\n## Propriétés à vérifier\n\nSelon le type réel :\n\n- id\n- name\n- reference\n- manufacturer\n- DN\n- PN\n- pressureClass\n- material\n- schedule\n- wallThicknessMm\n- service\n- spec\n- tag\n- tagFormatName\n- tagNumber\n- insulation\n- lineFunction\n- length\n- orientation\n- rotation\n- mirrored\n- documentation\n- notes\n\nNe pas ajouter artificiellement des champs impossibles à persister.\n\n---\n\n# 7 — FALLBACKS\n\nLes valeurs par défaut doivent être distinguées de la donnée réelle.\n\nExemple :\n\nSi le modèle contient `DN=200`, un fallback `DN=150` ne doit jamais écraser ou masquer la valeur 200.\n\nMême règle pour :\n\n- PN ;\n- material ;\n- schedule ;\n- service ;\n- spec ;\n- tag.\n\nUn fallback d\'affichage ne doit jamais être persisté comme donnée utilisateur sans action explicite.\n\n---\n\n# 8 — PERSISTENCE DES PROPRIÉTÉS\n\nPour chaque propriété importante :\n\n1. modifier dans Inspector ;\n2. changer de sélection ;\n3. fermer/réouvrir Inspector ;\n4. Undo ;\n5. Redo ;\n6. export JSON ;\n7. import JSON ;\n8. ouvrir viewer 3D.\n\nLa valeur finale doit rester identique.\n\n---\n\n# 9 — UNDO / REDO\n\nRéutiliser :\n\n- `commitGraph()`\n- `pushHistory()`\n- `undoGraph()`\n- `redoGraph()`\n\nUne commande ALIGN = une transaction.\n\nUne commande PARALLELE = une transaction.\n\nUne validation de plusieurs propriétés = une transaction logique.\n\nUndo/Redo doit préserver :\n\n- IDs ;\n- relations ;\n- nodes ;\n- segments ;\n- fittings ;\n- supports ;\n- CAD2D ;\n- dimensions ;\n- sélection lorsque possible.\n\n---\n\n# 10 — TESTS OBLIGATOIRES\n\n## ALIGN\n\n- 2 nodes\n- 3 nodes\n- N nodes\n- 2 segments\n- N segments\n- node + segment\n- fitting + segment\n- valve/equipment + segment si représentés par le modèle\n- support\n- CAD2D\n- dimension si transformable\n- sélection mixte compatible\n- référence explicite\n- anchor explicite\n- preview\n- Escape\n- validation\n- Undo\n- Redo\n- JSON export/import\n- aucun objet non sélectionné déplacé\n\n## PARALLELE\n\n- 2 segments\n- 3 segments\n- N segments\n- référence explicite\n- pivot from\n- pivot to\n- midpoint\n- preview\n- Escape\n- validation\n- Undo\n- Redo\n- JSON export/import\n- aucun objet non sélectionné déplacé\n\n## PROPRIÉTÉS\n\nTester au minimum :\n\n- DN\n- PN\n- material\n- schedule\n- service\n- spec\n- tag\n- orientation\n- rotation\n- référence\n- manufacturer\n\nsur les types réellement supportés.\n\n---\n\n# 11 — NON-RÉGRESSION\n\nTester :\n\n- création tube ;\n- node ;\n- tee ;\n- elbow ;\n- valve ;\n- fitting ;\n- sélection ;\n- multi-sélection ;\n- copy ;\n- paste ;\n- duplicate ;\n- delete ;\n- move ;\n- rotate ;\n- dimensions ;\n- labels ;\n- impression ;\n- JSON ;\n- viewer 3D ;\n- Undo ;\n- Redo.\n\n---\n\n# 12 — LIVRABLE\n\nCréer :\n\n`017Q2_IMPLEMENTATION_REPORT.md`\n\navec :\n\n- architecture réelle ;\n- fichiers modifiés ;\n- fonctions ajoutées/modifiées ;\n- Align ;\n- Parallel ;\n- sélection ;\n- anchors ;\n- propriétés bidirectionnelles ;\n- adapter inverse ;\n- Undo/Redo ;\n- sécurité topologique ;\n- preview ;\n- tests ;\n- régressions ;\n- risques résiduels.\n\nChaque test doit être :\n\n`PASS / PARTIAL / FAIL`\n\n---\n\n# 13 — CONDITION DE FIN\n\nLe patch est accepté uniquement si :\n\n### ALIGN\n\nTout élément géométriquement compatible du dessin peut être sélectionné et aligné sans devoir être groupé.\n\n### PARALLELE\n\nTout élément linéaire/géométriquement compatible peut être rendu parallèle à une référence.\n\n### PROPRIÉTÉS\n\nUne modification faite dans l\'inspector est réellement réinjectée dans le modèle et survit à export/import.\n\n### COHÉRENCE\n\n2D, 3D et JSON utilisent le même modèle.\n\n### HISTORIQUE\n\nAlign, Parallel et propriété sont annulables/rétablissables proprement.\n\n### SÉCURITÉ\n\nAucun objet non sélectionné ne bouge.\n\n### TOPOLOGIE\n\nAucune opération ne crée silencieusement un réseau incohérent.\n\n---\n\n# RÈGLE FINALE\n\nNe pas chercher à ajouter davantage de fonctionnalités.\n\nCe patch doit transformer les briques déjà présentes en système CAD cohérent :\n\n**TOUT ÉLÉMENT COMPATIBLE**\n→ sélectionner\n→ choisir référence\n→ choisir anchor\n→ aligner / rendre parallèle\n→ preview\n→ valider\n→ Undo/Redo\n→ JSON persistant\n\net :\n\n**TOUTE PROPRIÉTÉ ÉDITABLE**\n→ Inspector\n→ modèle réel\n→ persistance\n→ Undo/Redo\n→ 2D/3D cohérents.\n\nSTOP après ce patch et attendre validation humaine.\n', encoding="utf-8")
report.write_text(
    "# PD&I 017Q2 — PRECHECK\n\n"
    f"Date: {datetime.datetime.now().isoformat()}\n\n"
    "Le script ne modifie pas le code source et ne pousse rien vers GitHub.\n\n"
    "## Fichiers cibles\n\n" +
    "\n".join(
        f"- [{'OK' if r['exists'] else 'MISSING'}] `{r['path']}` — {r['bytes']} octets"
        for r in rows
    ) +
    "\n\n## Action\n\n"
    "Lire le brief puis effectuer l'audit réel avant toute modification.\n",
    encoding="utf-8",
)
print(f"Racine repo: {ROOT}")
print(f"Brief créé: {brief}")
print(f"Precheck créé: {report}")
print("Aucun push GitHub effectué.")
